import assert from 'node:assert/strict';
import {LivingSwarm} from './living.js';import {OrganismSwarm} from './organism_swarm.js';import {SwarmKlein} from './klein_bridge.js';import {MessyWorld} from './messy_world.js';import {GameEngineMorph} from './gameenginex_morph.js';import {teachMission} from './teacher_dialogue.js';
const S=new LivingSwarm({seed:3});for(let i=0;i<24;i++)S.add({gate:i+1,line:i%6+1,color:i%6+1,tone:i%6+1,base:i%5+1,dimension:['Movement','Evolution','Being','Design'][i%4]},'person',.3+(i%6)*.03,.3+Math.floor(i/6)*.03);const O=new OrganismSwarm(S);for(let i=0;i<5;i++)O.step();const G=new GameEngineMorph(O,new SwarmKlein(),new MessyWorld());
let calls=0;const constraints=[{path:['position','x'],equals:1},{path:['drives','creation'],minimum:.69}];
const teacher=async p=>{calls++;if(calls===1)return JSON.stringify({lesson:'bad',constraints,actions:['move']});assert.match(p,/Expected lesson/);return JSON.stringify({lesson:'Position describes location. Creation is a drive.',constraints});};
const r=await teachMission({instruction:'Reach x=1 and creation at least .69',teacher,habitat:G});assert.equal(r.status,'proposed-objective-met');assert.equal(calls,2);assert.equal(G.records.length,1);assert.ok(G.records[0].tree.plan.length>=2);assert.equal(r.events.find(e=>e.kind==='observation').steps.find(s=>s.step==='extract').checkWithSwarmGone,1);console.log('PASS: rejected teacher action recipe; retried with real rejection feedback; native swarm assembled and independently verified formation. Model response was a test double.');
const ctrl=new AbortController();ctrl.abort();assert.equal((await teachMission({instruction:'test',teacher,habitat:G,signal:ctrl.signal})).status,'stopped');assert.equal(calls,2);
const offline=await teachMission({instruction:'test',teacher:async()=>{throw Error('offline');},habitat:G});assert.equal(offline.status,'teacher-unavailable');assert.equal(offline.events.length,2);assert.equal(G.records.length,1);
// Transport-only test of failure feedback and unchanged goals; no execution claim for this test double.
let attempts=0, queries=0;const fixture={teach:()=>({lines:1,gaps:[]}),develop:()=>{attempts++;return {integrated:false,steps:[{step:'fail',reason:'unmet condition'}]};}};
const r2=await teachMission({instruction:'same objective',teacher:async p=>{queries++;if(queries>1)assert.match(p,/unmet condition/);return JSON.stringify({lesson:'Observe the conditions.',constraints:queries===1?constraints:[{path:['position','x'],equals:2}]});},habitat:fixture,maxTurns:2});assert.equal(r2.status,'unresolved');assert.equal(attempts,1);assert.equal(queries,2);console.log('PASS: unavailable teacher stops; execution feedback is returned; changed objective rejected.');
